262: export function collectTextures(jobs: CompileJob[]): THREE.Texture[] {
263:   const out = new Set<THREE.Texture>();
264:   const isTexture = (v: unknown): v is THREE.Texture => typeof v === 'object' && v !== null && (v as { isTexture?: boolean }).isTexture === true;
265:   const add = (v: unknown): void => { if (isTexture(v) && !v.isRenderTargetTexture) out.add(v); };
266:   const fromMaterial = (m: THREE.Material): void => {
267:     for (const v of Object.values(m)) add(v);
268:     for (const texture of shaderPatchTextures(m)) add(texture);
269:     const u = (m as THREE.Material & { uniforms?: Record<string, THREE.IUniform> }).uniforms;
270:     if (u) for (const uni of Object.values(u)) add(uni.value);
271:   };
272:   // the jobs' clones carry every scene material, the post-chain materials and the background box;
273:   // the target scenes carry the background / environment maps
274:   for (const job of jobs) {
275:     job.root.traverse((o) => { for (const m of materialsOf(o)) fromMaterial(m); });
276:     if (job.target) { add(job.target.background); add(job.target.environment); }
277:   }
278:   return [...out];

