358:     if (compressed) {
359:       // E257: iOS WebKit crashes in ANGLE UploadTextureContents when compressed uploads
360:       // accumulate without a GPU-process round trip. flush/finish alone do not prevent it.
361:       // Validate once per texture during boot, before queuing the next chain of mip levels.
362:       const gl = renderer.getContext();
363:       const error = gl.getError();
364:       if (error !== gl.NO_ERROR) throw new Error(`Graphics error ${error} after compressed texture ${i + 1}/${textures.length} (${tex.name || tex.format})`);
365:     }
366:     onProgress?.(base + i + 1, base + textures.length, `${i + 1} / ${textures.length} textures uploaded`);
367:     if (compressedArray || performance.now() - tSlice > 12) { await frame(); checkCurrent(); tSlice = performance.now(); }
368:   }
369:   checkCurrent();
370:   return { materials, jobs: jobs.length, programs: n, parallel };
371: }
